def workspace_tools(lab: CodingWorkspace) -> list[BaseTool]:
    """为独立工作台提供明确的读、写、测接口。

    Args:
        lab: 当前隔离工作台，写入许可由调用者明确设置。
    Returns:
        三个绑定到本工作台的工具，不含任意shell或目录参数。
    Raises:
        无：执行错误在调用时报告。
    """

    @tool
    def read_code() -> dict[str, Any]:
        """领取candidate.py和固定test_candidate.py，查看源码、测试与写入许可。"""
        return lab.read()

    @tool
    def edit_code(content: str) -> dict[str, Any]:
        """把完整候选源码写入candidate.py；不可改测试，保存后必须重新测试。"""
        return lab.edit(content)

    @tool
    async def run_tests() -> dict[str, Any]:
        """在隔离工作台运行固定unittest，返回真实结果和本次源码指纹。"""
        return await lab.run_tests()

    return [read_code, edit_code, run_tests]

